window.search = Object.assign(window.search, JSON.parse('{"results_options":{"limit_results":30,"teaser_word_count":30},"search_options":{"bool":"OR","expand":true,"fields":{"body":{"boost":1},"breadcrumbs":{"boost":1},"title":{"boost":2}}},"doc_urls":["intro.html","legal_norm.html#правна-норма","legal_fact.html#правен-факт","terms.html#понятия-по-азбучен-ред"],"index":{"fields":["title","body","breadcrumbs"],"pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5","index":{"body":{"root":{"docs":{},"df":0,"d":{"docs":{},"df":0,"i":{"docs":{},"df":0,"c":{"docs":{},"df":0,"o":{"docs":{"2":{"tf":1.0}},"df":1}}}},"f":{"docs":{},"df":0,"a":{"docs":{},"df":0,"c":{"docs":{},"df":0,"t":{"docs":{"2":{"tf":1.0}},"df":1}}}},"i":{"docs":{},"df":0,"u":{"docs":{"1":{"tf":1.0},"2":{"tf":1.0}},"df":2,"r":{"docs":{},"df":0,"i":{"docs":{},"df":0,"d":{"docs":{},"df":0,"i":{"docs":{},"df":0,"c":{"docs":{},"df":0,"u":{"docs":{"2":{"tf":1.0}},"df":1}}}}}}}},"l":{"docs":{},"df":0,"e":{"docs":{},"df":0,"g":{"docs":{},"df":0,"a":{"docs":{},"df":0,"l":{"docs":{"2":{"tf":1.0}},"df":1}}}}},"o":{"docs":{"0":{"tf":1.0}},"df":1}}},"breadcrumbs":{"root":{"docs":{},"df":0,"d":{"docs":{},"df":0,"i":{"docs":{},"df":0,"c":{"docs":{},"df":0,"o":{"docs":{"2":{"tf":1.0}},"df":1}}}},"f":{"docs":{},"df":0,"a":{"docs":{},"df":0,"c":{"docs":{},"df":0,"t":{"docs":{"2":{"tf":1.0}},"df":1}}}},"i":{"docs":{},"df":0,"u":{"docs":{"1":{"tf":1.0},"2":{"tf":1.0}},"df":2,"r":{"docs":{},"df":0,"i":{"docs":{},"df":0,"d":{"docs":{},"df":0,"i":{"docs":{},"df":0,"c":{"docs":{},"df":0,"u":{"docs":{"2":{"tf":1.0}},"df":1}}}}}}}},"l":{"docs":{},"df":0,"e":{"docs":{},"df":0,"g":{"docs":{},"df":0,"a":{"docs":{},"df":0,"l":{"docs":{"2":{"tf":1.0}},"df":1}}}}},"o":{"docs":{"0":{"tf":1.0}},"df":1}}},"title":{"root":{"docs":{},"df":0}}},"documentStore":{"save":true,"docs":{"0":{"body":"Теория на правото (или обща теория на правото) е основополагаща юридическа наука, която изследва основанията, същността и принципите на правната система. За разлика от отрасловите науки (като наказателно, гражданско, конституционно право), тя не се фокусира върху конкретни закони, а върху понятията, които съставляват „езика“ на правото. Същност на правото Естествено право: правото се основава на универсални морални принципи, разум или човешка природа. Правен позитивизъм: правото е сбор от норми, създадени и санкционирани от държавната власт, независимо от морала. Правна норма: oсновната градивна единица на правото. Тя представлява общозадължително правило за поведение, подкрепено от държавна принуда. Източници на правото: формите, чрез които правните норми получават официално признание (нормативни актове/закони, правен обичай, съдебен прецедент, международни договорености). Правно отношение: връзката между субектите на правото (физически или юридически лица), възникваща въз основа на правна норма, съдържаща техни субективни права и правни задължения. Правни понятия: основни термини като юридически факт, правосубектност (дееспособност и правоспособност), правонарушение и правна отговорност.","breadcrumbs":"Увод","id":"0","title":"Увод"},"1":{"body":"Нашата дума право, както и латинската ius, се употребява в два смисъла. Тя означава правната норма ( обективно право); тя означава и правната власт, която правната норма признава някому ( субективно право). Право е следователно и нормата, която задължава заемателя да върне на заемодавеца това, което е получил в заем; право е и властта на заемодавеца да иска от заемателя да му върне заетата сума. В първия случай говорим за обективно право, във втория – за субективно право.","breadcrumbs":"Правна Норма » Правна Норма","id":"1","title":"Правна Норма"},"2":{"body":"В правната теория и практика термините „юридически факт“ и „правен факт“ масово се използва като пълни синоними. Те обозначават конкретно обстоятелство от действителността, с осъществяването на което правната норма свързва настъпването на определени правни последици (поражда / променя / прекратява субективни права и задължения). Повечето български правни автори (като проф. Росен Ташев, проф. Живко Сталев и др.) предпочитат и използват основно термина юридически факт. Езиково разграничение Юридически факт: думата „юридически“ идва от латинското iuridicus (от ius — право и dico — казвам). Използва се като стандартен академичен термин в правната наука. Правен факт: по-често се среща в разговорната и популярната реч или в преводни текстове (напр. от руски — правовой факт, или от английски — legal fact), но има същия смисъл. Теоретично разграничение Някои теоретици на правото правят по-фина разлика въз основа на това дали фактът съществува в нормата или в реалния живот.","breadcrumbs":"Правен Факт » Правен Факт","id":"2","title":"Правен Факт"},"3":{"body":"","breadcrumbs":"Индекс » Понятия по азбучен ред","id":"3","title":"Понятия по азбучен ред"}},"docInfo":{"0":{"body":1,"breadcrumbs":0,"title":0},"1":{"body":1,"breadcrumbs":0,"title":0},"2":{"body":5,"breadcrumbs":0,"title":0},"3":{"body":0,"breadcrumbs":0,"title":0}},"length":4},"lang":"English"}}'));